<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Cache-Control: no-store');
function o(int $s,array $p):never{http_response_code($s);echo json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function db():PDO{static $p;if($p)return$p;$f=dirname(__DIR__,3).'/data.php';if(!is_file($f))o(500,['ok'=>false,'error'=>'DB config yok.']);$c=require$f;try{$p=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$c['host'],(int)$c['port'],$c['database']),$c['user'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return$p;}catch(Throwable $e){error_log('[notam] '.$e->getMessage());o(500,['ok'=>false,'error'=>'Veritabanına bağlanılamadı.']);}}
function utc($v):DateTimeImmutable{try{return new DateTimeImmutable(trim((string)$v)===''?'now':(string)$v,new DateTimeZone('UTC'));}catch(Throwable){o(400,['ok'=>false,'error'=>'Geçersiz UTC.']);}}
function idn(array$r):string{$s=strtoupper(trim((string)($r['series']??'')));$n=trim((string)($r['number']??''));$y=(string)($r['year']??'');$v=$s.$n;if($v==='')return(string)$r['nms_id'];if($y!==''&&!preg_match('/\/\d{2}$/',$v))$v.='/'.substr($y,-2);return$v;}
function cols(bool$t=true,bool$g=false):string{$a=['n.nms_id','n.series','n.number','n.year','n.notam_type','n.classification','n.affected_fir','n.location','n.icao_location','n.selection_code','n.traffic','n.purpose','n.scope','n.minimum_fl','n.maximum_fl','n.effective_start','n.effective_end','n.effective_end_raw','n.schedule','n.lower_limit','n.upper_limit','n.coordinates_raw','n.radius_nm','n.status','n.last_updated'];if($t)$a[]='n.notam_text';if($g)$a[]='ST_AsGeoJSON(n.geometry,6) geometry';return implode(',',$a);}
function item(array$r,bool$t=true):array{$x=['id'=>(string)$r['nms_id'],'ident'=>idn($r),'type'=>$r['notam_type']??null,'classification'=>$r['classification']??null,'fir'=>$r['affected_fir']??null,'location'=>$r['location']??null,'icaoLocation'=>$r['icao_location']??null,'selectionCode'=>$r['selection_code']??null,'traffic'=>$r['traffic']??null,'purpose'=>$r['purpose']??null,'scope'=>$r['scope']??null,'minimumFl'=>$r['minimum_fl']===null?null:(int)$r['minimum_fl'],'maximumFl'=>$r['maximum_fl']===null?null:(int)$r['maximum_fl'],'effectiveStart'=>$r['effective_start']??null,'effectiveEnd'=>$r['effective_end']??null,'effectiveEndRaw'=>$r['effective_end_raw']??null,'schedule'=>$r['schedule']??null,'lowerLimit'=>$r['lower_limit']??null,'upperLimit'=>$r['upper_limit']??null,'radiusNm'=>$r['radius_nm']===null?null:(float)$r['radius_nm'],'status'=>$r['status']??null,'lastUpdated'=>$r['last_updated']??null];if($t)$x['text']=$r['notam_text']??null;return$x;}
function state(array$r,DateTimeImmutable$a):string{if(($r['status']??'')==='cancelled')return'cancelled';$t=$a->getTimestamp();$s=$r['effective_start']?strtotime($r['effective_start'].' UTC'):false;$e=$r['effective_end']?strtotime($r['effective_end'].' UTC'):false;if($s!==false&&$s>$t)return'future';if(strtoupper((string)$r['effective_end_raw'])!=='PERM'&&$e!==false&&$e<$t)return'expired';return'valid';}
function add(array&$w,array&$p,string$c,string$k,string$v,string$rx):void{$v=strtoupper(trim($v));if($v!==''&&preg_match($rx,$v)){$w[]="$c=:$k";$p[$k]=$v;}}
function listx(PDO$p):never{$a=utc($_GET['at']??'');$st=strtolower((string)($_GET['state']??'valid'));$pg=max(1,(int)($_GET['page']??1));$lm=max(1,min(200,(int)($_GET['limit']??50)));$w=["n.source='FAA_NMS'","n.environment='production'"];$x=[];$ts=$a->format('Y-m-d H:i:s');if($st==='valid'){$w[]="n.status<>'cancelled'";$w[]='(n.effective_start IS NULL OR n.effective_start<=:a)';$w[]="(UPPER(COALESCE(n.effective_end_raw,''))='PERM' OR n.effective_end IS NULL OR n.effective_end>=:b)";$x['a']=$ts;$x['b']=$ts;}elseif($st==='future'){$w[]="n.status<>'cancelled'";$w[]='n.effective_start>:a';$x['a']=$ts;}elseif($st==='expired'){$w[]="n.status<>'cancelled'";$w[]="UPPER(COALESCE(n.effective_end_raw,''))<>'PERM'";$w[]='n.effective_end<:a';$x['a']=$ts;}elseif($st==='cancelled')$w[]="n.status='cancelled'";add($w,$x,"UPPER(COALESCE(n.affected_fir,''))",'fir',(string)($_GET['fir']??''),'/^[A-Z0-9]{4}$/');add($w,$x,"UPPER(COALESCE(n.notam_type,''))",'typ',(string)($_GET['type']??''),'/^[A-Z]{1,4}$/');add($w,$x,"UPPER(COALESCE(n.classification,''))",'cla',(string)($_GET['classification']??''),'/^[A-Z0-9_ -]{1,40}$/');add($w,$x,"UPPER(COALESCE(n.scope,''))",'scp',(string)($_GET['scope']??''),'/^[A-Z]{1,8}$/');add($w,$x,"UPPER(COALESCE(n.traffic,''))",'tra',(string)($_GET['traffic']??''),'/^[A-Z]{1,8}$/');add($w,$x,"UPPER(COALESCE(n.purpose,''))",'pur',(string)($_GET['purpose']??''),'/^[A-Z]{1,12}$/');add($w,$x,"UPPER(COALESCE(n.selection_code,''))",'sel',(string)($_GET['selection_code']??''),'/^[A-Z0-9]{1,12}$/');$icao=strtoupper(trim((string)($_GET['icao']??'')));if(preg_match('/^[A-Z0-9]{4}$/',$icao)){$w[]="(UPPER(COALESCE(n.icao_location,''))=:ic OR UPPER(COALESCE(n.location,''))=:lo)";$x['ic']=$icao;$x['lo']=$icao;}$q=trim((string)($_GET['q']??''));if($q!==''){$w[]='(n.nms_id LIKE :q1 OR n.notam_text LIKE :q2)';$x['q1']=$x['q2']='%'.$q.'%';}$ws=implode(' AND ',$w);$c=$p->prepare('SELECT COUNT(*) FROM notams n WHERE '.$ws);$c->execute($x);$total=(int)$c->fetchColumn();$off=($pg-1)*$lm;$ord=($_GET['sort']??'')==='start_asc'?'n.effective_start ASC':(($_GET['sort']??'')==='ident'?'n.series,n.number':'n.last_updated DESC');$s=$p->prepare('SELECT '.cols().' FROM notams n WHERE '.$ws.' ORDER BY '.$ord.' LIMIT '.$lm.' OFFSET '.$off);$s->execute($x);$it=[];while($r=$s->fetch()){$v=item($r);$v['temporalState']=state($r,$a);$it[]=$v;}$pages=$total?(int)ceil($total/$lm):0;o(200,['ok'=>true,'source'=>'FAA NMS','state'=>$st,'atUtc'=>$a->format('c'),'items'=>$it,'paging'=>['page'=>$pg,'limit'=>$lm,'returned'=>count($it),'total'=>$total,'pages'=>$pages,'hasPrevious'=>$pg>1,'hasNext'=>$pg<$pages]]);}
function filters(PDO$p):never{$z=[];foreach(['type'=>'notam_type','classification'=>'classification','scope'=>'scope','traffic'=>'traffic']as$k=>$c){$s=$p->query("SELECT DISTINCT $c value FROM notams WHERE source='FAA_NMS' AND environment='production' AND $c IS NOT NULL AND $c<>'' ORDER BY $c LIMIT 200");$z[$k]=array_values(array_filter(array_column($s->fetchAll(),'value')));}o(200,['ok'=>true,'source'=>'FAA NMS','options'=>$z]);}
function detail(PDO$p):never{$id=trim((string)($_GET['id']??''));$s=$p->prepare('SELECT '.cols()." FROM notams n WHERE n.source='FAA_NMS' AND n.environment='production' AND n.nms_id=:id LIMIT 1");$s->execute(['id'=>$id]);$r=$s->fetch();$r?o(200,['ok'=>true,'source'=>'FAA NMS','notam'=>item($r)]):o(404,['ok'=>false,'error'=>'NOTAM bulunamadı.']);}
function norm(float$v):float{while($v>180)$v-=360;while($v<-180)$v+=360;return$v;}
function mapx(PDO$p):never{foreach(['west','south','east','north']as$k)if(!is_numeric($_GET[$k]??null))o(400,['ok'=>false,'error'=>'bbox gerekli.']);$w=norm((float)$_GET['west']);$e=norm((float)$_GET['east']);$s=max(-85,min(85,(float)$_GET['south']));$n=max(-85,min(85,(float)$_GET['north']));$a=utc($_GET['at']??'');$t=$a->format('Y-m-d H:i:s');$poly=sprintf('POLYGON((%.7F %.7F,%.7F %.7F,%.7F %.7F,%.7F %.7F,%.7F %.7F))',$w,$s,$e,$s,$e,$n,$w,$n,$w,$s);$sql='SELECT '.cols(false,true)." FROM notams n WHERE n.source='FAA_NMS' AND n.environment='production' AND n.status<>'cancelled' AND (n.effective_start IS NULL OR n.effective_start<=:a) AND (UPPER(COALESCE(n.effective_end_raw,''))='PERM' OR n.effective_end IS NULL OR n.effective_end>=:b) AND n.geometry IS NOT NULL AND MBRIntersects(n.geometry,ST_GeomFromText(:g)) LIMIT 5000";$q=$p->prepare($sql);$q->execute(['a'=>$t,'b'=>$t,'g'=>$poly]);$f=[];while($r=$q->fetch()){$g=json_decode((string)$r['geometry'],true);if(!is_array($g))continue;$sel=strtoupper((string)($r['selection_code']??''));$grp=preg_match('/^Q(RD|RP|RR|RT)/',$sel)?'RESTRICTED_AIRSPACE':(preg_match('/^Q(WG|WL|WP|WT)/',$sel)?'AERIAL_SPORT':(preg_match('/^QWY/',$sel)?'AERIAL_SURVEY':(preg_match('/^Q(W[EFMU])/',$sel)?'TRAINING_MILITARY':'OTHER')));$f[]=['type'=>'Feature','geometry'=>$g,'properties'=>['layer'=>'notam','nms_id'=>(string)$r['nms_id'],'ident'=>idn($r),'classification'=>$r['classification'],'location'=>$r['location'],'icao_location'=>$r['icao_location'],'selection_code'=>$r['selection_code'],'effective_start'=>$r['effective_start'],'effective_end'=>$r['effective_end'],'effective_end_raw'=>$r['effective_end_raw'],'lower_limit'=>$r['lower_limit'],'upper_limit'=>$r['upper_limit'],'display_group'=>$grp,'geometry_source'=>'faa-geometry']];}o(200,['ok'=>true,'source'=>'FAA NMS','atUtc'=>$a->format('c'),'data'=>['type'=>'FeatureCollection','features'=>$f],'counts'=>['notam'=>count($f)],'truncated'=>count($f)>=5000]);}
try{$p=db();$a=strtolower((string)($_GET['action']??'list'));if($a==='list')listx($p);if($a==='filters')filters($p);if($a==='detail')detail($p);if($a==='map')mapx($p);if($a==='health')o(200,['ok'=>true,'records'=>(int)$p->query("SELECT COUNT(*) FROM notams WHERE source='FAA_NMS' AND environment='production'")->fetchColumn()]);o(400,['ok'=>false,'error'=>'Bilinmeyen action.']);}catch(Throwable$e){error_log('[notam] '.$e->getMessage());o(500,['ok'=>false,'error'=>'NOTAM isteği işlenemedi.']);}
